// Disposable page shell. All research transitions live in the pure ResearchModel.
const names={market:'大盘',sector:'相关板块',stock:'个股'};
const conclusions={support:'支持有限观察',oppose:'质疑观察',unknown:'尚不能判断'};
const applicability={fit:'本轮适用',uncertain:'适用性待确认',unfit:'本轮不适用'};
const choices={observe:'观察',continue:'继续观察',end:'结束观察',defer:'暂缓判断'};
const causes={object:'对象或三层依据变化',method:'方法适用性变化',evidence:'资料不足或补充',unchanged:'保留原解释'};
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,n=2)=>typeof v==='number'&&Number.isFinite(v)?v.toFixed(n):'--';
const pct=v=>typeof v==='number'&&Number.isFinite(v)?(v>0?'+':'')+v.toFixed(2)+'%':'--';
const pp=v=>typeof v==='number'&&Number.isFinite(v)?(v>0?'+':'')+v.toFixed(2)+' 个百分点':'--';
const keys=['market','sector','stock'];
let state=ResearchModel.create_state(HISTORY_DATA,{stock_code:'300502.SZ',start_date:'2025-03-03'});
const ui={layer:'market',drafts:{},decisionDraft:{},guide:'loop',guideStep:0,experiences:[],recordOpen:null};
const app=document.getElementById('app');
const val=id=>document.getElementById(id)?.value||'';
const checked=id=>!!document.getElementById(id)?.checked;
const selectOptions=(object,selected)=>Object.entries(object).map(([k,v])=>`<option value="${h(k)}" ${k===selected?'selected':''}>${h(v)}</option>`).join('');
function field(label,id,value='',type='text',wide=false){return `<div class="${wide?'wide':''}"><label for="${id}">${label}</label>${type==='textarea'?`<textarea id="${id}">${h(value)}</textarea>`:`<input id="${id}" type="${type}" value="${h(value)}">`}</div>`;}
function captureDrafts(){if(document.getElementById('layer-conclusion'))ui.drafts[state.as_of_date+ui.layer]={conclusion:val('layer-conclusion'),support:val('layer-support'),against:val('layer-against'),unknown:val('layer-unknown'),context:val('layer-context'),applicability:val('layer-applicability'),applicability_reason:val('layer-applicability-reason')};if(document.getElementById('decision-reason'))ui.decisionDraft={choice:document.querySelector('input[name="decision-choice"]:checked')?.value,reason:val('decision-reason'),focus:val('decision-focus'),review_cause:val('decision-cause'),context_note:val('decision-context')};}
function displayNotice(){const el=document.getElementById('action-feedback');el.textContent=state.notice.text;el.className='notice '+(state.notice.kind==='error'?'error':'');el.scrollIntoView({block:'nearest'});} function dispatch(action,after){captureDrafts();const next=ResearchModel.reduce(state,action,HISTORY_DATA);state=next;if(next.notice.kind==='error'){displayNotice();return false;}if(after)after();render();document.getElementById('action-feedback')?.scrollIntoView({block:'nearest'});return true;}
function stateStrip(){return `<div class="state-strip">${keys.map(key=>{const saved=state.layers[key];return `<div class="state-cell"><span class="fine muted">${names[key]} · ${h(state.methods[key].id)}</span><strong>${saved?conclusions[saved.conclusion]:'待研究'}</strong><span class="fine">${saved?`${applicability[saved.applicability]} · ${h(saved.context)}`:'先解释支持、质疑与仍未知的部分'}</span></div>`;}).join('')}</div>`;}
function inputSection(d){return `<section class="section" id="inputs"><div class="section-title"><h2>本轮对象与口径</h2><span class="badge">真实历史行情</span></div><p class="muted">先限定要回答的问题。默认试验仅观察日线价格结构；需要其他资料时，将它加入本轮并说明何时可知。</p><div class="fields"><div><label for="stock-code">手动指定个股</label><select id="stock-code">${HISTORY_DATA.groups.map(g=>`<optgroup label="${h(g.sector_name)} · ${h(g.sector_code)}">${g.stocks.map(s=>`<option value="${h(s.code)}" ${s.code===state.input.stock_code?'selected':''}>${h(s.name)} · ${h(s.code)}</option>`).join('')}</optgroup>`).join('')}</select></div><div><label for="start-date">历史研究日 · 盘后</label><input type="date" id="start-date" min="2025-01-02" max="2025-12-31" value="${state.input.start_date}"></div>${field('这次想判断什么','research-question',state.input.question,'textarea',true)}<div class="wide row">${keys.map(key=>`<div><label class="fine" for="period-${key}">${names[key]}观察周期</label><select id="period-${key}">${[5,10,20,60,120].map(n=>`<option value="${n}" ${n===state.input.periods[key]?'selected':''}>${n} 个交易日</option>`).join('')}</select></div>`).join('')}</div></div><div class="row" style="margin-top:16px"><button id="start-study" class="primary">${state.records.length?'按输入重新开始（清空本轮记录）':'按输入开始研究'}</button><span class="fine muted">使用样本内此前最近交易日。</span></div><div class="rule"></div><p class="fine"><strong>当前参照：</strong>沪深300（000300.SH） → ${h(state.input.sector_name)}（${h(state.input.sector_code)}，申万一级行业指数） → ${h(state.input.stock_name)}。板块来自路线图指定映射，2025 年实际成员关系未核实。各层收益窗口按大盘交易日对齐。</p><p class="fine warning"><strong>原型输入限制：</strong>股票使用真实不复权价格，跨除权的价变不能解释为纯收益；前复权研究系列尚未验收。历史行情为此次采集的快照，历史发布与后续修订时点未核实。</p><details><summary class="fine">查看必要输入、缺失与来源</summary><div class="table-wrap"><table class="evidence-table"><thead><tr><th>依据</th><th>本轮要求 / 状态</th><th>解释</th></tr></thead><tbody>${d.necessary_information.map(x=>`<tr><td>${h(x.label)}</td><td>${x.required?'必要':'可选'} · ${({provided:'已提供',missing:'缺失',unknown:'未知'})[x.status]||h(x.status)}</td><td>${h(x.reason)}</td></tr>`).join('')}</tbody></table></div><p class="fine footnote">默认问题收窄为价格结构；未核实的资料不会被自动解释为利好、利空或“没有事件”。</p></details><details style="margin-top:14px"><summary>加入当时可知的资料 / 标记必要资料缺失</summary><div class="fields" style="margin-top:14px">${field('资料内容，或缺少什么','extra-note',state.extra.note,'textarea',true)}${field('来源名称或链接','extra-source',state.extra.source)}${field('资料当时可得日期','extra-date',state.extra.available_date,'date')}<div><label for="extra-status">资料状态</label><select id="extra-status">${selectOptions({missing:'尚未提供',provided:'已提供且有日期来源'},state.extra.status)}</select></div><div class="row"><label class="check"><input type="checkbox" id="extra-required" ${state.extra.required?'checked':''}>本轮判断依赖这项资料</label></div></div><button id="save-extra" class="small" style="margin-top:12px">纳入本轮（需重新研究三层）</button><div class="rule"></div><label class="check"><input type="checkbox" id="missing-simulation" ${state.simulate_missing?'checked':''}>模拟：一项本轮必要资料不可得</label><p class="fine muted">此开关只改变资料覆盖情境，三层真实行情保持原值。</p>${field('模拟缺失的资料与影响','missing-reason',state.missing_reason||'本轮依赖的公告事实与可得时间未提供，无法解释价格变化是否伴随事件。','textarea',true)}<button id="apply-missing" class="small" style="margin-top:10px">应用资料情境（需重新研究三层）</button></details></section>`;}
function researchSection(d){const key=ui.layer,layer=d.layers[key],saved=state.layers[key],draft=ui.drafts[state.as_of_date+key]||saved||{},f=layer.factors;const order=keys.indexOf(key),locked=keys.slice(0,order).some(k=>!state.layers[k]);return `<section class="section" id="research"><div class="section-title"><h2>分别研究三层</h2><span class="fine muted">${h(state.as_of_date)} · 只见当时及此前</span></div><p class="muted">本轮先大盘、再相关板块、最后个股。每层独立留下判断和适用性；三层冲突时，选择仍由你解释。</p>${stateStrip()}<div class="tabs" role="tablist" aria-label="三层研究">${keys.map(k=>`<button role="tab" id="tab-${k}" aria-selected="${key===k}" data-layer="${k}" aria-controls="layer-panel">${names[k]}<span>${h(d.layers[k].name)} · ${state.layers[k]?'已提交':'待研究'}</span></button>`).join('')}</div><div id="layer-panel" role="tabpanel" aria-labelledby="tab-${key}"><div class="row spread"><h3>${h(layer.name)} <span class="muted fine">${h(layer.code)}</span></h3><span class="badge">${h(state.methods[key].id)} · 试验假设</span></div><p class="fine muted">${h(state.methods[key].question)} 研究均线与价变，人工解释支持、质疑和未知；不会自动给出观察结论。</p>${layer.stale?`<p class="warning">本研究日行情缺失，最后已知 bar 为 ${h(layer.latest?.trade_date)}；不能把它当作研究日价格。</p>`:''}<div class="metrics"><div class="metric"><span>${layer.period} 交易日价格变化 · 非总收益</span><strong>${pct(f.return_n)}</strong></div><div class="metric"><span>相对大盘 · 同一窗口</span><strong>${key==='market'?'参照本身':pp(f.relative_market_n)}</strong></div><div class="metric"><span>相对板块 · 同一窗口</span><strong>${key==='stock'?pp(f.relative_sector_n):'作为下一层参照'}</strong></div><div class="metric"><span>20 日收盘价最大回撤</span><strong>${pct(f.max_drawdown_20)}</strong></div><div class="metric"><span>5 日均量 / 20 日均量</span><strong>${num(f.volume_ratio_5_20)}${typeof f.volume_ratio_5_20==='number'?' 倍':''}</strong></div><div class="metric"><span>原始收盘 · ${h(layer.latest?.trade_date||'无行情')}</span><strong>${num(layer.latest?.close)}</strong></div></div><p class="fine muted">价变窗口 ${h(f.from_date||'预热不足')} → ${h(f.to_date)}；均线与回撤仅用此前数据，未知缺口影响的结果保留 --。</p><div id="chart-root"></div><div class="row fine muted footnote"><a href="${h(layer.source_url)}" target="_blank" rel="noreferrer">查看${h(layer.source_id||'行情')}来源</a><span>此次采集的历史快照</span></div><div class="research-editor"><h3>留下本层解释</h3>${locked?`<p class="warning">可先查看本层行情；请先提交${names[keys[order-1]]}解释，再提交本层。</p>`:''}<div class="fields"><div><label for="layer-conclusion">本层结论</label><select id="layer-conclusion">${selectOptions(conclusions,draft.conclusion||'unknown')}</select></div><div><label for="layer-applicability">本层方法的适用性</label><select id="layer-applicability">${selectOptions(applicability,draft.applicability||'uncertain')}</select></div>${field('支持依据 · 从哪些事实看出','layer-support',draft.support||'','textarea')}${field('质疑依据 · 有哪些反对证据','layer-against',draft.against||'','textarea')}${field('仍未知 · 哪些结论不能作出','layer-unknown',draft.unknown||'','textarea',true)}${field('当前情境 · 怎样理解这段走势','layer-context',draft.context||'','textarea')}${field('为何适用、存疑或不适用','layer-applicability-reason',draft.applicability_reason||'','textarea')}</div><div class="row" style="margin-top:15px"><button id="save-layer" class="primary" ${locked?'disabled':''}>保存${names[key]}解释${key!=='stock'?'并研究下一层':''}</button>${saved?'<span class="fine muted">修改上层解释后，引用它的下层需重新提交。</span>':''}</div></div></div></section>`;}
function decisionSection(d){const draft=ui.decisionDraft,complete=keys.every(k=>state.layers[k]);const prior=state.records.at(-1);return `<section class="section" id="decision"><div class="section-title"><h2>组合依据，留下观察选择</h2><span class="badge">${h(state.methods.combination.id)} / ${h(state.methods.observation.id)}</span></div><div class="table-wrap"><table class="evidence-table"><thead><tr><th>层次</th><th>判断与适用性</th><th>支持 / 质疑 / 未知</th></tr></thead><tbody>${keys.map(k=>{const s=state.layers[k];return `<tr><td>${names[k]}</td><td>${s?`${conclusions[s.conclusion]}<br><span class="fine muted">${applicability[s.applicability]}</span>`:'待提交'}</td><td>${s?`<div>支持：${h(s.support||'尚未提供')}</div><div>质疑：${h(s.against||'尚未提供')}</div><div class="muted">未知：${h(s.unknown||'未补充')}</div>`:'先留下本层解释'}</td></tr>`;}).join('')}</tbody></table></div>${d.context.has_required_missing?'<p class="warning" style="margin-top:14px">有本轮必要资料缺失。可以暂缓判断；若保留有限观察，请明确如何收窄范围。</p>':''}<p class="fine muted" style="margin-top:14px">三层判断、情境与其他资料由你组合；本轮没有自动评分、上层否决或买入动作。</p><div class="decision-choices">${Object.entries(choices).map(([k,label])=>`<label><input type="radio" name="decision-choice" value="${k}" ${draft.choice===k?'checked':''}>${label}</label>`).join('')}</div><div class="fields">${field('选择理由 · 哪些依据共同支持它','decision-reason',draft.reason||'','textarea',true)}${field('下次复核关注点 · 看什么才能改变判断','decision-focus',draft.focus||'','textarea',true)}<div><label for="decision-cause">这轮主要复核什么</label><select id="decision-cause">${selectOptions(causes,draft.review_cause||'object')}</select></div>${field('判断范围与关键资料不足的处理','decision-context',draft.context_note||'','textarea')}</div><div class="row" style="margin-top:15px"><button id="save-decision" class="primary" ${!complete?'disabled':''}>保存选择与当时完整快照</button><span class="fine muted">${complete?'原记录不会覆盖，可在回看中查看。':'三层分别提交后可保存。'}</span></div>${state.decision?`<div class="notice" style="margin-top:15px">已保存：${choices[state.decision.choice]} · ${h(state.decision.record_id)}。可以推进时间复核。</div>`:''}${prior?`<details style="margin-top:15px"><summary>对照上次选择的理由和关注点</summary><p style="margin-top:10px">${h(prior.as_of_date)} · ${choices[prior.decision.choice]}：${h(prior.decision.reason)}</p><p class="muted">关注：${h(prior.decision.focus)}</p></details>`:''}</section>`;}
function replaySection(d){const feedback=state.last_feedback;return `<section class="section" id="replay"><div class="section-title"><h2>推进时间，复核三层变化</h2><span class="fine numeric muted">当前 ${state.as_of_date}</span></div><p class="muted">先保存本时点选择，再沿沪深300真实交易日推进。推进后重新研究三层，复核原理由及方法适用性，再留下新的选择。</p><div class="row">${[1,5,10,20].map(n=>`<button data-advance="${n}" ${state.decision?'':'disabled'}>推进 ${n} 个交易日</button>`).join('')}</div>${feedback?`<div class="rule"></div><p><strong>${h(feedback.from_date)} → ${h(feedback.to_date)}</strong> · 已推进 ${feedback.actual_steps} 个真实交易日</p><p class="fine">原理由：${h(feedback.prior_reason)}<br>原关注点：${h(feedback.prior_focus)}</p><div class="table-wrap"><table class="evidence-table feedback-table"><thead><tr><th>层次</th><th>原判断</th><th>前 / 后窗口价变*</th><th>前 / 后回撤</th><th>本轮复核</th></tr></thead><tbody>${keys.map(k=>{const x=feedback.layer_changes[k],now=state.layers[k];return `<tr><td>${names[k]}</td><td>${conclusions[x.previous_conclusion]}<br><span class="fine muted">${applicability[x.previous_applicability]}</span></td><td>${pct(x.before.return_n)} / ${pct(x.after.return_n)}</td><td>${pct(x.before.max_drawdown_20)} / ${pct(x.after.max_drawdown_20)}</td><td>${now?`${conclusions[now.conclusion]} · ${applicability[now.applicability]}`:'请重新研究'}</td></tr>`;}).join('')}</tbody></table></div><p class="fine muted">* 各层使用自己设定的周期；比较两个研究日各自窗口的价格结构。${h(feedback.note)}</p><button id="review-now" class="primary" style="margin-top:10px">回到大盘，开始本轮复核</button>`:'<p class="empty" style="margin-top:16px">首次选择尚未推进。保存观察、结束或暂缓后，才揭晓下一时点。</p>'}</section>`;}
function methodSection(){return `<section class="section" id="methods"><div class="section-title"><h2>本轮方法与版本</h2><span class="badge">全部为试验假设</span></div><p class="muted">六项方法解释各自解决什么问题、需要什么输入，以及如何复核。阶段一可修订解释并另存版本；方法替换的效果比较留给下一阶段。</p><div class="method-list">${Object.entries(state.methods).map(([key,m])=>`<details class="method-row"><summary>${h(m.name)} <span class="badge">${h(m.id)}</span></summary><p>${h(m.question)}</p><dl><dt class="muted fine">所需输入</dt><dd>${h(m.required_inputs)}</dd><dt class="muted fine">适用假设</dt><dd>${h(m.assumptions)}</dd><dt class="muted fine">输出用途</dt><dd>${h(m.output_use)}</dd><dt class="muted fine">复核依据</dt><dd>${h(m.review_basis)}</dd></dl><label class="fine" for="method-${key}">本版本解释 / 下一版本修订理由</label><textarea id="method-${key}">${h(m.explanation)}</textarea><button class="small" data-revise="${key}" style="margin-top:10px">另存为 v${m.version+1}（重提关联判断）</button></details>`).join('')}</div></section>`;}
function recordDetail(r){return `<div class="record-copy"><dl><dt>对象与问题</dt><dd>${h(r.input.stock_name)}（${h(r.input.stock_code)}）\n${h(r.question)}</dd><dt>研究时点</dt><dd>${h(r.as_of_date)} · 日线盘后 · 仅使用该日及此前bar</dd><dt>三层参照</dt><dd>沪深300 → ${h(r.input.sector_name)}（${h(r.input.sector_code)}） → ${h(r.input.stock_name)}\n${h(r.input.sector_mapping)}\n周期：${keys.map(k=>`${names[k]} ${r.input.periods[k]}交易日`).join(' / ')}</dd><dt>选择理由</dt><dd>${h(r.decision.reason)}</dd><dt>仍需复核</dt><dd>${h(r.decision.focus)}</dd><dt>判断范围</dt><dd>${h(r.decision.context_note||r.input.scope)}\n${h(causes[r.decision.review_cause])}</dd></dl>${keys.map(k=>{const x=r.layers[k],f=r.visible.layers[k].factors;return `<div><h3>${names[k]} · ${conclusions[x.conclusion]} · ${applicability[x.applicability]}</h3><p class="fine">情境：${h(x.context)}<br>适用性：${h(x.applicability_reason)}<br>支持：${h(x.support||'未提供')}<br>质疑：${h(x.against||'未提供')}<br>未知：${h(x.unknown||'未补充')}</p><p class="fine numeric muted">${f.period}日价变 ${pct(f.return_n)} · MA5 ${num(f.ma5)} / MA10 ${num(f.ma10)} / MA20 ${num(f.ma20)} · 回撤 ${pct(f.max_drawdown_20)} · 量比 ${num(f.volume_ratio_5_20)}<br>${h(r.visible.layers[k].source_id)} · ${h(r.visible.layers[k].price_basis)} · 截止bar ${h(r.visible.layers[k].latest?.trade_date)}</p></div>`;}).join('')}<details><summary class="fine">当时的全部方法版本、资料与输入限制</summary>${Object.values(r.methods).map(m=>`<p class="fine" style="margin-top:10px"><strong>${h(m.name)} ${h(m.id)}</strong><br>${h(m.explanation)}</p>`).join('')}<p class="fine">${r.simulated_missing?'模拟资料不足：'+h(r.missing_reason):'未开启资料不足模拟'}<br>补充资料：${h(r.extra.note||'未提供')} · ${h(r.extra.available_date||'日期未知')} · ${h(r.extra.source||'来源未知')}</p><ul class="fine muted">${r.data_scope.map(s=>`<li>${h(s)}</li>`).join('')}</ul></details></div>`;}
function historySection(){return `<section class="section" id="history"><div class="section-title"><h2>回看判断与原型发现</h2><button id="export-records" class="small" ${state.records.length||ui.experiences.length?'':'disabled'}>导出本轮记录 JSON</button></div><p class="fine muted">内存中记录 ${state.records.length} 次判断；刷新会清空。导出包含当时的三层bar、因素、人工解释、资料及六项方法版本，不包含未来行情。</p>${state.records.length?state.records.map(r=>`<details class="record" ${r.id===ui.recordOpen?'open':''}><summary><strong>${h(r.as_of_date)} · ${choices[r.decision.choice]}</strong><span class="fine muted">第 ${r.sequence} 次 · ${h(r.methods.combination.id)}</span></summary>${recordDetail(r)}</details>`).join(''):'<p class="empty">完成三层研究并保存选择后，这里可以回看当时的完整依据。</p>'}<div class="rule"></div><h3>记录这次体验发现</h3><p class="fine muted">记录流程是否帮助解释选择、哪里难理解，以及下一轮想改变什么。体验发现与方法有效性证据分别保留；本轮不自动宣布正式功能取舍。</p>${field('体验发现 / 待验证的问题','experience-note','','textarea',true)}<button id="save-experience" class="small" style="margin-top:10px">留下体验发现</button>${ui.experiences.map(x=>`<p class="fine" style="margin-top:12px"><strong>${h(x.as_of_date)} · 待使用者验证</strong><br>${h(x.note)}</p>`).join('')}<details style="margin-top:18px"><summary class="fine">完整操作记录与版本关系</summary><ol class="fine muted">${state.log.map(x=>`<li>${h(x.as_of_date)} · ${h(x.description)}</li>`).join('')||'<li>尚无操作记录。</li>'}</ol><p class="fine">方法版本：${state.method_history.map(m=>h(m.id)).join(' → ')}</p></details></section>`;}
const guides={loop:{name:'观察与复核',code:'300502.SZ',date:'2025-03-03',description:'使用新易盛、通信与沪深300的真实历史。按钮逐步提交试验解释；每步后可查看状态，也可自由修改。解释只示范怎样留痕，不预设涨跌或方法有效。'},missing:{name:'资料不足与暂缓',code:'688506.SH',date:'2025-03-03',description:'真实行情保持原值，明确模拟必要公告资料缺失。分别保留三层未知，暂缓并推进，再复核资料范围。'},versions:{name:'方法修订与回看',code:'600036.SH',date:'2025-03-03',description:'用招商银行、银行与沪深300走通记录，修订情境方法解释，重新研究后另存判断；原记录继续关联v1。'} };
function guideSteps(){return [['market','提交大盘试验解释'],['sector','提交板块试验解释'],['stock','提交个股试验解释'],['decision','保存首次观察选择'],['advance','推进 10 个真实交易日'],...(ui.guide==='versions'?[['revise','修订情境解释，另存 v2']]:[]),['market','复核大盘与适用性'],['sector','复核板块与适用性'],['stock','复核个股与适用性'],['decision','保存本轮重新判断'],['view','回看两次依据与方法版本']];}
function guideSection(){const g=guides[ui.guide];return `<section class="section" id="guide"><h2>分步演练与自由操作</h2><p class="muted">可直接用上面的控件研究，也可按下列场景逐步走通。开始场景会重置当前内存任务；每一步执行真实状态操作，并即时显示反馈。</p><div class="tabs" role="tablist" aria-label="引导演练场景">${Object.entries(guides).map(([key,x])=>`<button role="tab" aria-selected="${key===ui.guide}" data-guide="${key}">${x.name}</button>`).join('')}</div><p class="fine">${h(g.description)}</p><button id="restart-guide" class="small">${state.records.length?'重置本轮，开始此场景':'开始 / 重置此场景'}</button><ol class="guide">${guideSteps().map(([type,label],i)=>`<li><button class="small ${i===ui.guideStep?'primary':''}" data-guide-step="${i}" ${i!==ui.guideStep?'disabled':''}>${h(label)}</button><span class="fine muted">${i<ui.guideStep?'已完成':i===ui.guideStep?'当前一步':'接续前一步'}</span></li>`).join('')}</ol><p class="fine muted">三层结论采用人工解释的试验样例，可在自由操作中改为支持、质疑或未知。模拟资料不足仅出现在明确标注的场景。</p></section>`;}
function render(){const d=ResearchModel.derive(state,HISTORY_DATA);app.innerHTML=`<main class="page"><header class="intro"><div class="row spread"><h1>个股观察与复核</h1><span class="badge warning">阶段一 · 可丢弃逻辑原型</span></div><p class="muted">要验证的问题：给定个股后，三层分别研究能否支持一次说得清的观察选择，并在时间推进后重新判断？</p><p class="fine muted">真实 2025 年行情 · 方法与交互均为试验假设 · 记录仅在本页内存中，导出可保留</p></header><div class="shell"><aside class="rail"><strong>本轮研究</strong><nav aria-label="观察流程">${[['inputs','确定输入'],['research','三层研究'],['decision','观察选择'],['replay','时间与复核'],['history','记录回看']].map(([id,title],i)=>`<a href="#${id}"><span class="step-number">${i+1}</span>${title}</a>`).join('')}</nav><div class="rail-state"><strong>${h(state.input.stock_name)}</strong><dl class="fine"><dt>研究日</dt><dd class="numeric">${state.as_of_date}</dd><dt>相关板块</dt><dd>${h(state.input.sector_name)}</dd><dt>观察状态</dt><dd>${({new:'首次待判断',observing:'正在观察',ended:'已结束观察',deferred:'已暂缓'})[state.observation_status]}</dd><dt>三层解释</dt><dd>${keys.filter(k=>state.layers[k]).length} / 3 已提交</dd><dt>判断记录</dt><dd>${state.records.length} 次</dd><dt>情境方法</dt><dd>${h(state.methods.context.id)}</dd></dl><a class="fine" href="#guide">分步演练</a><br><a class="fine" href="#methods">方法与版本</a></div></aside><div class="workspace"><div id="action-feedback" class="notice ${state.notice.kind==='error'?'error':''}" role="status" aria-live="polite">${h(state.notice.text)}</div><section class="section" id="current-state"><div class="section-title"><h2>当前研究状态</h2><span class="numeric">${state.as_of_date}</span></div><p><strong>${h(state.input.stock_name)}</strong> → 沪深300 / ${h(state.input.sector_name)} · ${state.input.periods.stock} 交易日观察</p>${stateStrip()}<p class="fine">观察选择：${state.decision?choices[state.decision.choice]+' · '+h(state.decision.reason):'本时点尚未记录'}<br>资料情境：${state.simulate_missing?'模拟必要资料缺失':'真实历史样本，其他资料依覆盖保留未知'} · 情境 ${h(state.methods.context.id)} / 组合 ${h(state.methods.combination.id)} / 观察 ${h(state.methods.observation.id)}</p></section>${guideSection()}${inputSection(d)}${researchSection(d)}${decisionSection(d)}${replaySection(d)}${methodSection()}${historySection()}<footer class="fine muted">所有输入与方法均可在体验后调整。原型用来推敲研究流程；本轮尚未验证方法有效性或形成正式功能取舍。</footer></div></div></main>`;ResearchChart.mount(document.getElementById('chart-root'),{...d.layers[ui.layer],as_of_date:state.as_of_date},ResearchModel.calendar(HISTORY_DATA));bind();}
function resetGuide(key=ui.guide){ui.guide=key;ui.guideStep=0;ui.layer='market';ui.drafts={};ui.decisionDraft={};ui.recordOpen=null;ui.experiences=[];const g=guides[key];state=ResearchModel.create_state(HISTORY_DATA,{stock_code:g.code,start_date:g.date});if(key==='missing')state=ResearchModel.reduce(state,{type:'set_missing',enabled:true,reason:'模拟：本轮需要的公告事实及当时可得时间缺失，无法检查事件解释。'},HISTORY_DATA);render();}
function sampleExplanation(key){const d=ResearchModel.derive(state,HISTORY_DATA).layers[key],f=d.factors;const unknown=ui.guide==='missing'||f.return_n===null;return {type:'save_layer',layer:key,conclusion:'unknown',support:!unknown?`真实价格事实：${f.period}交易日价变 ${pct(f.return_n)}，MA20 ${num(f.ma20)}。这些事实可作为有限价格结构观察的输入。`:'行情可以查看，关键资料覆盖仍不足。',against:'单项价变或均线位置不能独自决定观察；公司行动和历史资料覆盖未完整核实。',unknown:ui.guide==='missing'?'模拟：缺少本轮必要公告资料，不推断无事件或利好利空。':'价格事实怎样支持观察仍需人工解释；历史成员、基本面与公司行动未知。',context:`试验解释：${names[key]}在${state.as_of_date}的${f.period}日价格结构，基于真实行情，保留情境未知。`,applicability:'uncertain',applicability_reason:'仅用于有限价格结构研究；未知公司行动或必要资料时收窄解释，不宣称方法已有效。'};}
function runGuideStep(i){if(i!==ui.guideStep)return;const [type]=guideSteps()[i];let action=null;if(keys.includes(type)){action=sampleExplanation(type);ui.layer=type;}else if(type==='decision'){const isReview=state.records.length>0;action={type:'save_decision',choice:ui.guide==='missing'?'defer':isReview?'continue':'observe',reason:ui.guide==='missing'?'必要资料尚不足，保留三层未知并暂缓。':'试验样例：三层价格事实已分别记录，但结论保留未知；仅为收集后续证据开展有限观察，不把观察视为确认趋势。',focus:'复核三层价格结构、原未知资料，以及方法适用解释是否需要改变。',review_cause:ui.guide==='missing'?'evidence':isReview?'unchanged':'object',context_note:'判断范围限定为价格结构的有限观察；不推断基本面、事件、总收益或买入条件。'};}else if(type==='advance'){action={type:'advance',steps:10};ui.drafts={};ui.decisionDraft={};ui.layer='market';}else if(type==='revise')action={type:'revise_method',key:'context',explanation:'试验修订：将公司行动与关键资料覆盖单列为未知，复核时分别解释对象变化、资料不足与方法可能不适用；一次价变不证明方法失效。'};else if(type==='view'){ui.recordOpen=state.records[0]?.id;ui.guideStep++;render();document.getElementById('history').scrollIntoView({block:'start'});return;}
  captureDrafts();const next=ResearchModel.reduce(state,action,HISTORY_DATA);state=next;if(next.notice.kind!=='error'){ui.guideStep++;if(keys.includes(type))delete ui.drafts[state.as_of_date+type];if(type==='revise')ui.drafts={};if(type==='decision')ui.decisionDraft={};}render();document.getElementById(type==='advance'?'replay':type==='decision'?'decision':type==='revise'?'methods':'research').scrollIntoView({block:'start'});
}
function bind(){
  document.querySelectorAll('[data-layer]').forEach(button=>button.onclick=()=>{captureDrafts();ui.layer=button.dataset.layer;render();document.getElementById('research').scrollIntoView({block:'start'});});
  document.getElementById('start-study').onclick=()=>{const options={stock_code:val('stock-code'),start_date:val('start-date'),question:val('research-question'),periods:Object.fromEntries(keys.map(k=>[k,+val('period-'+k)]))};const next=ResearchModel.create_state(HISTORY_DATA,options);if(next.notice.kind==='error'){state={...state,notice:next.notice};displayNotice();return;}state=next;ui.layer='market';ui.drafts={};ui.decisionDraft={};ui.guideStep=0;ui.experiences=[];render();document.getElementById('research').scrollIntoView({block:'start'});};
  document.getElementById('save-layer').onclick=()=>{const layer=ui.layer;dispatch({type:'save_layer',layer,conclusion:val('layer-conclusion'),support:val('layer-support'),against:val('layer-against'),unknown:val('layer-unknown'),context:val('layer-context'),applicability:val('layer-applicability'),applicability_reason:val('layer-applicability-reason')},()=>{if(layer!=='stock')ui.layer=keys[keys.indexOf(layer)+1];});if(state.notice.kind!=='error')document.getElementById(layer==='stock'?'decision':'research').scrollIntoView({block:'start'});};
  document.getElementById('save-decision').onclick=()=>dispatch({type:'save_decision',choice:document.querySelector('input[name="decision-choice"]:checked')?.value,reason:val('decision-reason'),focus:val('decision-focus'),review_cause:val('decision-cause'),context_note:val('decision-context')},()=>{ui.decisionDraft={};document.getElementById('replay')?.scrollIntoView({block:'start'});});
  document.querySelectorAll('[data-advance]').forEach(button=>button.onclick=()=>{dispatch({type:'advance',steps:+button.dataset.advance},()=>{ui.layer='market';ui.drafts={};ui.decisionDraft={};});document.getElementById('replay').scrollIntoView({block:'start'});});
  const review=document.getElementById('review-now');if(review)review.onclick=()=>{captureDrafts();ui.layer='market';render();document.getElementById('research').scrollIntoView({block:'start'});};
  document.querySelectorAll('[data-revise]').forEach(button=>button.onclick=()=>{const key=button.dataset.revise;dispatch({type:'revise_method',key,explanation:val('method-'+key)},()=>{ui.drafts={};ui.decisionDraft={};ui.layer='market';});});
  document.getElementById('save-extra').onclick=()=>dispatch({type:'set_extra',note:val('extra-note'),source:val('extra-source'),available_date:val('extra-date'),status:val('extra-status'),required:checked('extra-required')},()=>{ui.drafts={};ui.layer='market';});
  document.getElementById('apply-missing').onclick=()=>dispatch({type:'set_missing',enabled:checked('missing-simulation'),reason:val('missing-reason')},()=>{ui.drafts={};ui.layer='market';});
  document.querySelectorAll('[data-guide]').forEach(button=>button.onclick=()=>resetGuide(button.dataset.guide));
  document.getElementById('restart-guide').onclick=()=>resetGuide();
  document.querySelectorAll('[data-guide-step]').forEach(button=>button.onclick=()=>runGuideStep(+button.dataset.guideStep));
  document.getElementById('save-experience').onclick=()=>{const note=val('experience-note').trim();if(!note){state={...state,notice:{kind:'error',text:'请先写下体验发现或待验证问题。'}};render();return;}captureDrafts();ui.experiences.push({as_of_date:state.as_of_date,user_id:'admin',status:'pending_user_validation',note});state={...state,notice:{kind:'success',text:'体验发现已留在本轮内存中，可随研究记录导出；尚未作为正式功能决定。'}};render();document.getElementById('history').scrollIntoView({block:'start'});};
  document.getElementById('export-records').onclick=()=>{const snapshot={prototype:true,user_id:'admin',records:state.records,method_history:state.method_history,experiences:ui.experiences,log:state.log,data_metadata:HISTORY_DATA.metadata};const url=URL.createObjectURL(new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='PROTOTYPE_stock_research_'+state.input.stock_code+'_'+state.as_of_date+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
window.addEventListener('resize',()=>{const d=ResearchModel.derive(state,HISTORY_DATA);ResearchChart.mount(document.getElementById('chart-root'),d.layers[ui.layer],ResearchModel.calendar(HISTORY_DATA));});
render();
